const sql = `DELETE FROM trading.news_items ni
  WHERE ni.status = 'discarded' AND ni.created_at < now() - interval '21 days'
    -- FIX 2026-07-31 (Phase 11 Nachtrag, Nutzerentscheidung): news_assessments.news_id ist ein
    -- FOREIGN KEY (NO ACTION) auf news_items.id, und live bestaetigt haben 452/452 discarded
    -- Zeilen eine Bewertung - ohne diesen Guard waere der DELETE gescheitert, sobald die erste
    -- discarded-Zeile 21 Tage alt wird. Konsistent mit der 365-Tage-Regel: eine bereits bewertete
    -- News bleibt dauerhaft erhalten, diese Regel greift dadurch praktisch nur noch fuer den
    -- seltenen Fall unbewerteter discarded-Zeilen (Sicherheitsnetz, keine aktive Bereinigung mehr).
    AND NOT EXISTS (
      SELECT 1 FROM trading.news_assessments na WHERE na.news_id = ni.id
    );`;
return { json: { ...$json, sql, stufe: 'discarded_21d' } };

