const sql = `DELETE FROM trading.news_items ni
  WHERE ni.status = 'evaluated'
    AND ni.created_at < now() - interval '365 days'
    AND NOT EXISTS (
      SELECT 1 FROM trading.news_impact_tracking nit WHERE nit.news_id = ni.id
    )
    -- FIX 2026-07-31 (Phase 11 Bestandsaufnahme-Nachtrag): news_assessments.news_id hat einen
    -- FOREIGN KEY (NO ACTION, keine CASCADE) auf news_items.id. Eine 'evaluated' News hat so
    -- gut wie immer eine Bewertungszeile - ohne diesen Guard waere der DELETE fuer praktisch
    -- jede real betroffene Zeile an der Fremdschlüssel-Pruefung gescheitert, sobald erstmals
    -- echte Daten 365 Tage alt werden (bisher latent, da noch keine Zeile so alt ist).
    -- Nutzerentscheidung: eine bereits bewertete News bleibt dauerhaft erhalten (Nachvollzieh-
    -- barkeit vergangener Bewertungen/Entscheidungen hat Vorrang vor Speicherplatz-Ersparnis).
    AND NOT EXISTS (
      SELECT 1 FROM trading.news_assessments na WHERE na.news_id = ni.id
    );`;
return { json: { ...$json, sql, stufe: 'evaluated_365d' } };

