// Paket 19 (Phase 11 der fachlichen Ueberarbeitung, 2026-07-31): Archivierung statt Loeschung.
// Voll ausgewertete News, deren Wirkungsmessung abgeschlossen ist (news_impact_tracking.status
// = 'completed', nicht nur "irgendeine Zeile existiert" wie bei der 365-Tage-Regel oben) und
// die alt genug sind, um nicht mehr aktiv gebraucht zu werden, werden auf status='archived'
// umgestellt statt geloescht - die Zeile bleibt fuer Audit/Lernen/spaetere Simulation vollstaendig
// erhalten (siehe docs/DATENAUFBEWAHRUNG.md), zaehlt aber nicht mehr als "aktiv" mit.
// Aktuell dormant: die Wirkungsmessung braucht bis zu 20 Handelstage bis 'completed', das
// System ist erst ~12 Tage alt - noch keine Zeile erfuellt beide Bedingungen. Korrektes
// Verhalten fuer spaeter, kein Fehler.
const sql = `UPDATE trading.news_items ni
  SET status = 'archived'
  WHERE ni.status = 'evaluated'
    AND ni.created_at < now() - interval '180 days'
    AND EXISTS (
      SELECT 1 FROM trading.news_impact_tracking nit
      WHERE nit.news_id = ni.id AND nit.status = 'completed'
    );`;
return { json: { ...$json, sql, stufe: 'archivierung_evaluiert' } };

// Paket 19 (Phase 11): reine Betriebs-Logs (pipeline_runs/workflow_errors) sind keine
// fachlichen Daten mit Lernwert - anders als Bewertungen/Wirkungsdaten duerfen sie nach einer
// grosszuegigen Frist geloescht werden (siehe docs/DATENAUFBEWAHRUNG.md, Kategorie
// "Fehlerprotokolle"/"temporaere Payloads"). Keine Fremdschluessel von anderen Tabellen auf
// diese beiden Tabellen (live per information_schema geprueft, 2026-07-31) - Loeschung ist
// unbedenklich.
const sql = `DELETE FROM trading.pipeline_runs WHERE created_at < now() - interval '180 days';
DELETE FROM trading.workflow_errors WHERE occurred_at < now() - interval '180 days';`;
return { json: { ...$json, sql, stufe: 'betriebslog_bereinigung' } };
